// Carousel — Shared data re-exported from curated carousel data
// Each variant uses unique photos with hand-written descriptions.
//
// The photos are the example's own placeholder images: one 800x500 SVG per
// photo, committed in examples/carousel/images/ and generated by
// scripts/generate-example-images.mjs. The site serves them from the project
// root, so the page makes no third-party image requests.

import {
  getItems,
  getItemCount,
  getItemWidth,
} from "../../src/data/carousel.js";

export { getItems, getItemCount, getItemWidth };

/** URL of a photo's image. The size arguments of the callers are kept because
 * the detail panel and the slide template ask for different sizes; one vector
 * file covers all of them. */
export function getImageUrl(picId) {
  return `/examples/carousel/images/${picId}.svg`;
}

/** Warm the browser cache for a variant's photos. */
export function preloadImages(variant) {
  return Promise.all(
    getItems(variant).map(
      (item) =>
        new Promise((resolve) => {
          const img = new Image();
          img.onload = img.onerror = resolve;
          img.src = getImageUrl(item.picId);
        }),
    ),
  );
}
